// Capture actual flows around processing, before population growth changes next month's demand.
export function wasteState(c){return c.tiles.reduce((s,t)=>{s.waiting+=t.waste||0;if(t.type==='landfill'){s.stored+=t.garbage;s.decay+=Math.min(.5,t.garbage);}if(t.type==='recycling')s.recycled+=t.recycledLastMonth||0;if(['incinerator','wasteEnergy'].includes(t.type))s.burned+=t.burnedLastMonth||0;return s;},{waiting:0,stored:0,decay:0,recycled:0,burned:0});}
export function wasteMonth(generated,before,imported,processed,exported){return{garbageGenerated:generated,garbageImported:Math.max(0,imported.waiting-before.waiting),garbageRecycled:processed.recycled,garbageIncinerated:processed.burned,garbageLandfilled:Math.max(0,processed.stored-imported.stored+imported.decay),garbageExported:Math.max(0,processed.waiting-exported.waiting),garbageUncollected:exported.waiting};}
export const WASTE_METHODS={garbageRecycled:'Recycled',garbageIncinerated:'Incinerated',garbageLandfilled:'Landfilled',garbageExported:'Exported'};
export function wasteBreakdown(c){const fields=['garbageGenerated','garbageImported','garbageUncollected',...Object.keys(WASTE_METHODS)],rows=c.history.filter(h=>h.month>c.month-12&&fields.every(k=>Number.isFinite(h[k]))),latest=rows.at(-1);if(!latest)return null;const total=Object.keys(WASTE_METHODS).reduce((s,k)=>s+latest[k],0);return{month:latest.month,generated:latest.garbageGenerated,imported:latest.garbageImported,waiting:latest.garbageUncollected,total,methods:Object.entries(WASTE_METHODS).map(([key,name])=>({name,amount:latest[key],percent:total?latest[key]/total*100:0})),recordedMonths:rows.length,yearGenerated:rows.reduce((s,h)=>s+h.garbageGenerated,0)};}
